prompt:
Create unit `tasks` and implement `find_last`: return the index of the last element equal to v, or a.len() if there is none. The contract must state both cases: at the returned index (if any) the element is v and no later element is v; if a.len() is returned, no element is v.

Required signature (in unit `tasks`):
fn find_last(a: &[i64], v: i64) -> (r: usize)

reference.code:
spec fn absent_from(a: &[i64], v: i64, n: usize) -> bool { forall|k: usize| n <= k && k < a.len() ==> #[trigger] a[k] != v }

spec fn last_ok(a: &[i64], v: i64, r: usize) -> bool {
    r <= a.len() && (r < a.len() ==> a[r] == v && (forall|k: usize| r < k && k < a.len() ==> #[trigger] a[k] != v)) && (r == a.len() ==> absent_from(a, v, 0))
}

#[effects(pure)]
#[uses(absent_from, last_ok)]
fn find_last(a: &[i64], v: i64) -> (r: usize)
    ensures last_ok(a, v, r),
{
    let mut k: usize = a.len();
    while k > 0 && a[k - 1] != v
        invariant k <= a.len(), absent_from(a, v, k),
        decreases k,
    {
        k = k - 1;
    }
    if k == 0 {
        a.len()
    } else {
        k - 1
    }
}

